```cpp
bool operator<(const PhysicsBodyKey &other) const {
	if (physics_layer == other.physics_layer) {
		if (linear_velocity == other.linear_velocity) {
			if (angular_velocity == other.angular_velocity) {
				if (one_way_collision == other.one_way_collision) {
					if (one_way_collision && y_origin != other.y_origin) {
						return y_origin < other.y_origin;
					}
					return one_way_collision_margin < other.one_way_collision_margin;
				}
				return one_way_collision < other.one_way_collision;
			}
			return angular_velocity < other.angular_velocity;
		}
		return linear_velocity < other.linear_velocity;
	}
	return physics_layer < other.physics_layer;
}
