```csharp
private IEnumerable<DacGcReference> walkAll()
{
    if (_handleWalkMask != 0)
    {
        foreach (DacGcReference reference in WalkHandles())
            yield return reference;
    }

    // External memory handles are strong roots, but are stored independently of the GC handle table.
    if (_handleWalkMask.HasFlag(CorGCReferenceType.CorHandleStrong))
    {
        foreach (DacGcReference reference in WalkExternalMemoryHandles())
            yield return reference;
    }

    if (_walkStacks)
    {
        foreach (DacGcReference reference in WalkStacks())
            yield return reference;
    }
}
```

```cpp
Vector2i TileAtlasView::get_atlas_tile_coords_at_pos(const Vector2 p_pos, bool p_clamp) const {
	if (tile_set_atlas_source.is_null()) {
		return Vector2i();
	}

	Ref<Texture2D> texture = tile_set_atlas_source->get_texture();
	if (texture.is_null()) {
		return TileSetSource::INVALID_ATLAS_COORDS;
	}

	Vector2i margins = tile_set_atlas_source->get_margins();
	Vector2i separation = tile_set_atlas_source->get_separation();
	Vector2i texture_region_size = tile_set_atlas_source->get_texture_region_size();

	// Compute index in atlas.
	Vector2 pos = p_pos - margins;
	Vector2i ret = (pos / (texture_region_size + separation)).floor();

	// Clamp.
	if (p_clamp) {
		Vector2i size = tile_set_atlas_source->get_atlas_grid_size();
		ret = ret.clamp(Vector2i(), size - Vector2i(1, 1));
	}

	return ret;
}
```

