```csharp
protected void expand_labeled(
    ReadOnlySpan<byte> prk,
    ReadOnlySpan<byte> label,
    ReadOnlySpan<byte> info,
    Span<byte> output)
{
    Debug.Assert(KeyDerivationKdf.IsTwoStage);
    Debug.Assert(prk.Length == KeyDerivationKdf.Nh);
    Debug.Assert(output.Length <= ushort.MaxValue);

    ReadOnlySpan<byte> suiteId = Suite.KemMetadata.SuiteId;
    int labeledInfoLength =
        checked(sizeof(ushort) + VersionLabel.Length + suiteId.Length + label.Length + info.Length);
    const int MaxStackLabeledInfoLength = 512;
    Span<byte> labeledInfoBuffer = stackalloc byte[MaxStackLabeledInfoLength];
    Span<byte> destination = labeledInfoBuffer.Slice(0, labeledInfoLength);
    BinaryPrimitives.WriteUInt16BigEndian(destination, checked((ushort)output.Length));
    int offset = sizeof(ushort);
    VersionLabel.CopyTo(destination.Slice(offset));
    offset += VersionLabel.Length;
    suiteId.CopyTo(destination.Slice(offset));
    offset += suiteId.Length;
    label.CopyTo(destination.Slice(offset));
    offset += label.Length;
    info.CopyTo(destination.Slice(offset));

    HKDF.Expand(KeyDerivationKdf.HkdfHashAlgorithm, prk, output, destination);
}
```

```csharp
private static bool ApplyMarshalAs(
    LoweringContext context,
    CustomAttributeValue<SerializationTypeCode> arguments)
{
    var descriptor = new BlobBuilder();
    if (!TryBuildMarshallingDescriptor(context, arguments, descriptor))
    {
        return false;
    }

    switch (context.Owner)
    {
        case EntityRegistry.FieldDefinitionEntity field:
            field.MarshallingDescriptor = descriptor;
            return true;

        case EntityRegistry.ParameterEntity parameter:
            parameter.MarshallingDescriptor = descriptor;
            return true;

        case EntityRegistry.PropertyEntity property:
            ApplyMarshalAsToProperty(context.Registry, property, descriptor);
            return true;

        default:
            return context.InvalidTarget();
    }
}
```

```cpp
void AudioStreamRandomizer::_move_stream(int p_index_from, int p_index_to) {
	ERR_FAIL_INDEX(p_index_from, audio_stream_pool.size());
	// p_index_to == audio_stream_pool.size() is valid (move to end).
	ERR_FAIL_COND(p_index_to < 0);
	ERR_FAIL_COND(p_index_to > audio_stream_pool.size());
	audio_stream_pool.insert(p_index_to, audio_stream_pool[p_index_from]);
	// If 'from' is strictly after 'to' we need to increment the index by one because of the insertion.
	if (p_index_from > p_index_to) {
		p_index_from++;
	}
	audio_stream_pool.remove_at(p_index_from);
	emit_signal(CoreStringName(changed));
	notify_property_list_changed();
}
