```csharp
public override JsonModelItem deserialize(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
{
    switch (reader.TokenType)
    {
        case JsonTokenType.String:
            string? stringItem = reader.GetString();
            if (stringItem is null || stringItem.Length == 0)
            {
                throw new JsonException("deserialized json string item was null or the empty string");
            }

            return new JsonModelItem(stringItem, metadata: null);

        case JsonTokenType.StartObject:
            Dictionary<string, string>? dictionary = JsonSerializer.Deserialize<Dictionary<string, string>>(ref reader, options);
            if (dictionary is null)
            {
                return null!;
            }

            var caseInsensitiveDictionary = new Dictionary<string, string>(dictionary, StringComparer.OrdinalIgnoreCase);
            if (!caseInsensitiveDictionary.TryGetValue("Identity", out string? identity))
            {
                throw new JsonException("deserialized json dictionary item did not have a non-empty Identity metadata");
            }

            if (identity is null || identity.Length == 0)
            {
                throw new JsonException("deserialized json dictionary item did not have a non-empty Identity metadata");
            }

            caseInsensitiveDictionary.Remove("Identity");
            return new JsonModelItem(identity, caseInsensitiveDictionary);

        default:
            throw new NotSupportedException();
    }
}
```

```cpp
Variant construct_empty_value_for_data_type(const GDScriptDataType &P_TYPE) {
	if (P_TYPE.kind == GDScriptDataType::BUILTIN) {
		if (P_TYPE.builtin_type == Variant::ARRAY) {
			Array array;
			// Typed array.
			if (P_TYPE.has_container_element_type(0)) {
				const GDScriptDataType &element_type = P_TYPE.get_container_element_type(0);
				array.set_typed(element_type.builtin_type, element_type.native_type, element_type.script_type);
			}

			return array;
		} else if (P_TYPE.builtin_type == Variant::DICTIONARY) {
			Dictionary dict;
			// Typed dictionary.
			if (P_TYPE.has_container_element_types()) {
				const GDScriptDataType &key_type = P_TYPE.get_container_element_type_or_variant(0);
				const GDScriptDataType &value_type = P_TYPE.get_container_element_type_or_variant(1);
				dict.set_typed(key_type.builtin_type, key_type.native_type, key_type.script_type, value_type.builtin_type, value_type.native_type, value_type.script_type);
			}

			return dict;
		} else {
			Callable::CallError ce;
			Variant variant;
			Variant::construct(P_TYPE.builtin_type, variant, nullptr, 0, ce);

			ERR_FAIL_COND_V(ce.error != Callable::CallError::CALL_OK, Variant());

			return variant;
		}
	}

	return Variant();
}
