def _get_out_move_values(self, OutMove):
    picking = OutMove.picking_id
    source = OutMove._get_source_document()
    partner_info, picking_info, source_info = False, False, False
    if source and source != picking:
        source_info = {
            'id': source.id,
            'res_model': source._name,
            'display_name': source.display_name,
        }
    if picking:
        picking_info = {
            'id': picking.id,
            'res_model': 'stock.picking',
            'display_name': picking.display_name,
        }
        partner_info = {
            'id': picking.partner_id.id,
            'res_model': 'res.partner',
            'display_name': picking.partner_id.display_name,
        } if picking.partner_id else False
    # To handle different UoM quantities, all qties will be expressed in product's UoM.
    reserved_quantity = OutMove.quantity
    if OutMove.uom_id != OutMove.product_id.uom_id:
        reserved_quantity = OutMove.product_id.uom_id._compute_quantity(reserved_quantity, OutMove.uom_id)
    return {
        **OutMove.read(['date', 'priority', 'state'])[0],
        'favorite': OutMove.priority == '1',
        'id': OutMove.id,
        'is_reserved': bool(OutMove.move_orig_ids),
        'move_orig_ids': OutMove.move_orig_ids.ids,
        'partner': partner_info,
        'picking': picking_info,
        'reserved_quantity': reserved_quantity,
        'quantity': OutMove.product_qty,
        'source': source_info,
        'uom': OutMove.product_id.uom_id.read(['display_name', 'factor'])[0],
    }
